// Simplified ICEGATE-style flat file (.sb). In production this is generated by the backend.
import { lineTotal, valueOr } from '@/shipping-bills/model/calculations'
import type { ShippingBill } from '../api-types'

function field(value: string | number | undefined) {
  return String(value ?? '').replace(/[\^\r\n]+/g, ' ')
}

function row(values: (string | number | undefined)[]) {
  return `<R>${values.map(field).join('^')}`
}

export function generateFlatFile({ id, values }: ShippingBill) {
  const header = `ZZ*${values.loadingPort}*ZZ*ICEGATE*01*SB*1.0*`
  const lines = [
    `HREC**${header}`,
    '<TABLE>SHIPPING_BILL',
    '<F>MESSAGE_TYPE^CHA_ID^JOB_NO^JOB_DATE^EXPORTER_ID^EXPORTER_BRANCH^CONSIGNEE_ID^LOADING_PORT^DEST_PORT^DISCHARGE_PORT^SEAL_TYPE^NATURE_OF_CARGO^GROSS_WEIGHT^NET_WEIGHT^UOM^PACKAGES^MARKS',
    row([
      'F',
      1000,
      values.jobNumber ?? id,
      values.jobDate,
      values.exporterId,
      values.exporterBranchId,
      values.consigneeId,
      values.loadingPort,
      values.finalDestinationPort,
      valueOr(values.dischargePort, values.finalDestinationPort),
      values.sealType,
      values.natureOfCargo,
      values.grossWeight,
      values.netWeight,
      values.measurementUnit,
      values.totalPackages,
      values.marksAndNumbers
    ]),
    '<TABLE>INVOICE',
    '<F>INVOICE_SN^INVOICE_NO^INVOICE_DATE^CURRENCY^CONTRACT_TYPE^BUYER_ID^FREIGHT_AMOUNT^INSURANCE_AMOUNT',
    ...values.invoices.map((invoice, index) =>
      row([
        index + 1,
        invoice.invoiceNumber,
        invoice.invoiceDate,
        invoice.currency,
        invoice.contractType,
        invoice.buyerSameAsConsignee ? values.consigneeId : invoice.buyerId,
        valueOr(invoice.freightAmount, '0'),
        valueOr(invoice.insuranceAmount, '0')
      ])
    ),
    '<TABLE>ITEM',
    '<F>INVOICE_SN^ITEM_SN^RITC_CODE^DESCRIPTION^QUANTITY^UOM^UNIT_PRICE^LINE_TOTAL^SCHEME_CODE',
    ...values.invoices.flatMap((invoice, invoiceIndex) =>
      invoice.items.map((item, itemIndex) =>
        row([
          invoiceIndex + 1,
          itemIndex + 1,
          item.ritcCode,
          item.goodsDescription1,
          item.quantity,
          item.unitOfMeasurement,
          item.unitPrice,
          lineTotal(item).toFixed(2),
          item.schemeCode
        ])
      )
    )
  ]

  if (values.packingRanges.length > 0) {
    lines.push(
      '<TABLE>PACKING',
      '<F>FROM_PKG^TO_PKG^PKG_CODE',
      ...values.packingRanges.map((range) =>
        row([range.packingNumberFrom, range.packingNumberTo, valueOr(range.packingCode, 'CTN')])
      )
    )
  }

  lines.push(`TREC**${header}`)
  return { filename: `shipping_bill_${values.jobNumber ?? id}.sb`, content: lines.join('\r\n') }
}
